"\"<?php\n// Script untuk menambahkan kolom Nilai Akhir Skripsi di view\n\n\$content = file_get_contents('src/views/scores/submit.php');\n\n// Tambahkan kolom di header\n\$content = preg_replace('/<th>NIM<\\/th>\\s*<th>Nama<\\/th>\\s*(<\\?php foreach \\(\\$availableStages as \\$stageCode => \\$stageLabel\\): \\?>\\s*<th><\\?= htmlspecialchars\\(\\$stageLabel\\) \\?><\\/th>\\s*<\\?php endforeach; \\?>)/', \"<th>NIM</th>\\n                                    <th>Nama</th>\\n                                    \\$1\\n                                    <th>Nilai Akhir Skripsi</th>\", \$content);\n\n// Tambahkan kolom di setiap baris data\n\$content = preg_replace('/<td><\\?= htmlspecialchars\\(\\$student\\[\\'nim\\'\\]\\) \\?><\\/td>\\s*<td>\\s*<div><\\?= htmlspecialchars\\(\\$student\\[\\'name\\'\\]\\) \\?><\\/div>/', \"<td><?= htmlspecialchars(\$student['nim']) ?></td>\\n                                        <td>\\n                                            <div><?= htmlspecialchars(\$student['name']) ?></div>\", \$content);\n\n// Simpan perubahan\nfile_put_contents('src/views/scores/submit.php', \$content);\n\necho \"View berhasil diperbarui!\\n\";\n?>\""